def get_segments(points):
    byk=defaultdict(list)
    for c,r in points: byk[c-r].append((c,r))
    segs=[]
    for k,ps in byk.items():
        rs=sorted(r for c,r in ps)
        groups=[]
        for rr in rs:
            if not groups or rr>groups[-1][-1]+1: groups.append([rr])
            else: groups[-1].append(rr)
        for g in groups:
            vs=[2*r+k for r in g]
            segs.append((k,min(vs),max(vs)))
    return segs

def predict_fill(points):
    ss=get_segments(points)
    filled=set()
    for i,(k1,a1,b1) in enumerate(ss):
      for k2,a2,b2 in ss[i+1:]:
        lo,hi=sorted((k1,k2)); v0=max(a1,a2);v1=min(b1,b2)
        if lo==hi or v0>v1: continue
        for r in range(16):
          for c in range(16):
            u=c-r; v=c+r
            if lo<u<hi and v0<=v<=v1 and (c,r) not in points:
              filled.add((r,c))
    return filled,ss
